CREATE TABLE "public"."materials" (
  "id"            bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name"          text                     NOT NULL,
  "category"      text                     NOT NULL DEFAULT 'Inne'::text,
  "unit"          text                     NOT NULL DEFAULT 'szt'::text,
  "price"         numeric                  NOT NULL DEFAULT 0,
  "supplier"      text,
  "symbol"        text,
  "created_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "price_history" jsonb                    NOT NULL DEFAULT '[]'::jsonb,
  CONSTRAINT "materials_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."materials"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "materials_all_staff" ON "public"."materials"
  FOR ALL
  TO PUBLIC
  USING ((public.current_role_name() IS NOT NULL))
  WITH CHECK ((public.current_role_name() IS NOT NULL));

REVOKE ALL ON SEQUENCE "public"."materials_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."materials_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."materials_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."materials_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."materials_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."materials_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."materials_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."materials_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."materials" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."materials" TO "service_role";

REVOKE ALL ON TABLE "public"."materials" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."materials" TO "postgres";
